package br.com.conectatea.vinculo.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="consentimentos") public class Consentimento { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="responsavel_id") private Long responsavelId; @Column(name="crianca_id") private Long criancaId; @Column(name="profissional_id") private Long profissionalId; private boolean aceito; @Column(name="termo_versao") private String termoVersao; private String finalidade; @Column(name="data_aceite") private Instant dataAceite; @Column(name="data_revogacao") private Instant dataRevogacao; private String ip; @Column(name="user_agent") private String userAgent; @Column(name="created_at") private Instant createdAt=Instant.now(); protected Consentimento(){} public Consentimento(Long r,Long c,Long p,String ip,String ua){responsavelId=r;criancaId=c;profissionalId=p;aceito=true;termoVersao="1.0";finalidade="Acompanhamento terapêutico da criança";dataAceite=Instant.now();this.ip=ip;userAgent=ua;} }
